        "skeleton": {
          "setup": "主角处于被轻视、被污蔑或被认为无能的弱势位置，且手中握有尚未亮出的、足以推翻对方判断的硬事实或真实能力。",
          "escalation": [
            "轻视者当众抛出质疑或污蔑，把矛盾推到不可回避的公开场合，围观者形成一边倒的舆论压力。",
            "主角不辩解、不争口舌，以沉默或低姿态积蓄势能，让围观者的轻蔑达到峰值。",
            "主角在关键节点亮出无可辩驳的事实或能力，一举推翻轻视者的全部前提。"
          ],
          "payoff": "轻视者失语、围观者态度瞬间逆转，主角的「事实碾压」兑现为强烈的打脸爽感与地位抬升。",
          "aftermath": "承认或反扑的余波被处理：轻视者或降级或转为忌惮，旁观者中产生新的敬畏与依附，为下一波冲突埋下种子。"
        },
